{"candidate": {"id": "C05-requant-fused", "level": "L1", "template": "L1.saturate_clamp", "title": "Lệnh dịch-làm tròn-kẹp bão hoà int8 một chu kỳ (rqsat)", "target": "layers.conv1 — phần chu kỳ phân loại 'requant' (cycles_by_sem_sum10.requant = 921470.0), và layers.conv2.cycles_by_sem_sum10.requant = 369060.0", "evidence": ["share_by_sem_total.requant = 8.84; cycles_by_sem_total.requant = 129053.0 (loại chu kỳ lớn thứ ba)", "amdahl_max_speedup_total.requant = 1.1", "layers.conv1.share_by_sem.requant = 24.91 (lớn thứ ba trong conv1, sau mac 42.4 và load_data 26.48)", "layers.conv1.amdahl_max_speedup.requant = 1.33", "layers.conv2.share_by_sem.requant = 3.67; layers.conv2.cycles_by_sem_sum10.requant = 369060.0", "layers.conv1.cycles_sum10 = 3699090 (lớp lớn thứ hai sau conv2)"], "spec": {"encoding": {"opcode": "0x0b (custom-0)", "funct3": "0x2", "funct7": "0x00 = dịch có làm tròn nửa lên rồi kẹp [-128,127]; 0x01 = dịch cắt bỏ (truncate) rồi kẹp — chọn biến thể khớp đúng firmware"}, "semantics_python": "def sem(rs1, rs2, state):
    # rqsat: rd = clamp( round_shift_right( signed(rs1), rs2[4:0] ), -128, 127 ), tra ve dang mo rong dau 32 bit
