", "latency_cycles": 1, "firmware_changes": "Thay chuỗi hậu kỳ mỗi điểm đầu ra ('addi acc,acc,1<<(s-1)' / 'srai acc,acc,s' / cặp so sánh-rẽ nhánh hoặc slt+select để kẹp về [-128,127]) bằng một 'rqsat acc, s'. PHẢI đối chiếu chuỗi thật trong firmware trước: nếu firmware cắt bỏ thay vì làm tròn nửa lên thì dùng funct7=0x01 để giữ đúng từng bit với golden. Phần nhân với hệ số requant giữ nguyên (vẫn là mul, hoặc gộp bằng C04).", "hw_resources_guess": {"MULT18X18": 0, "BSRAM": 0, "LUT4": "nhỏ: một bộ dịch phải số học đã có + bộ cộng bit làm tròn + hai bộ so sánh hằng số", "DFF": 0, "new_arch_regs": 0}}, "estimate_method": "iss_plugin", "expected_mechanism": "Cắt loại chu kỳ 'requant' (8.84% toàn mô hình, 24.91% trong conv1): gộp 3-4 lệnh vô hướng mỗi điểm đầu ra thành 1 lệnh 1 chu kỳ. Giảm n_c của lớp alu/shift/branch. Vì conv1 có requant chiếm gần một phần tư chu kỳ của lớp, đây là ứng viên rẻ nhất cho conv1.", "risks": ["Độ đúng là rủi ro CHÍNH: phải khớp chính xác quy tắc làm tròn (nửa lên / về 0 / nửa chẵn) và điểm kẹp của firmware, nếu không kết quả lệch so với golden. Hai biến thể funct7 có để chọn, nhưng cần xác nhận bằng mã nguồn firmware.", "Dịch với s = 0: nhánh 1 << (s-1) phải tránh — ngữ nghĩa ở trên đã xử lý s == 0 thành đồng nhất.", "Fmax: thấp — dịch + cộng + kẹp là đường tổ hợp ngắn hơn đường nhân hiện có.", "Tệp thanh ghi: không đổi.", "Phức tạp hiện thực: thấp."]}, "estimate": {"method": "C_amdahl_ceiling", "base_cycles": 1459993, "targeted_cycles": 129053, "fraction": 0.0884, "max_speedup": 1.097, "formula": "tăng tốc ≤ 1/(1−f)", "classes": ["requant"], "layers": null, "confidence": "CHẶN TRÊN, không phải dự báo", "matched_pattern": "requant|lượng tử"}, "base_config": "B-V1"}

{"candidate": {"id": "C11-mac-array-4x4", "level": "L4", "template": "L4.mac_array", "title": "Mảng MAC 4x4 gắn sát CPU với bộ đệm trọng số/activation cục bộ", "target": "layers.conv2 (cycles_sum10 = 10054190, bound = "compute/issue") và layers.conv1 (cycles_sum10 = 3699090, bound = "compute/issue")", "evidence": ["layers.conv2.bound = "compute/issue"; layers.conv2.dist_to_roof_x = 3.19; layers.conv2.mac_per_cycle = 0.1386 so với roof_mac_per_cycle = 0.4428", "layers.conv1.bound = "compute/issue"; layers.conv1.dist_to_roof_x = 13.22; layers.conv1.mac_per_cycle = 0.1316 so với roof_mac_per_cycle = 1.7399", "share_by_sem_total.mac = 40.47 và share_by_sem_total.load_data = 44.5", "layers.conv2.byte_per_mac = 4.516 với mem_bytes_per_cycle_available = 2.0 (cần tái sử dụng dữ liệu, đúng tín hiệu của mẫu L4.mac_array)", "layers.conv2.mac = 139392 và layers.conv1.mac = 48672 mỗi ảnh", "layers.dense.bound = "compute/issue"; layers.dense.dist_to_roof_x = 7.27"], "spec": {"encoding": {"opcode": "0x5b (custom-2)", "funct3": "0x0 = nạp hàng activation vào đệm; 0x1 = nạp cột trọng số vào đệm; 0x2 = chạy một bước mảng 4x4; 0x3 = đọc một ô kết quả ra rd", "funct7": "chọn hàng/cột/ô (0x00-0x0f)"}, "semantics_python": "def sem(rs1, rs2, state):
    # Mang MAC 4x4 trong kien truc: ACC[i][j] += A[i] * W[j] cho i,j in 0..3,
    # voi A, W la hai dem 4 phan tu int8 nap truoc tu DMEM.
    f3 = state.get('funct3', 0)
    acc = state.setdefault('ARR', [[0] * 4 for _ in range(4)])
    if f3 == 0:
        state['A'] = [((rs1 >> (8 * k)) & 0xFF) - 256 if ((rs1 >> (8 * k)) & 0x80) else ((rs1 >> (8 * k)) & 0xFF) for k in range(4)]
        return 0, state
    if f3 == 1:
        state['W'] = [((rs1 >> (8 * k)) & 0xFF) - 256 if ((rs1 >> (8 * k)) & 0x80) else ((rs1 >> (8 * k)) & 0xFF) for k in range(4)]
        return 0, state
    if f3 == 2:
        for i in range(4):
            for j in range(4):
                acc[i][j] = (acc[i][j] + state['A'][i] * state['W'][j]) & 0xFFFFFFFF
        return 0, state
    sel = state.get('funct7', 0) & 0x0F
    v = acc[sel >> 2][sel & 3]
    if state.get('funct7', 0) & 0x10:
        acc[sel >> 2][sel & 3] = 0
    return v & 0xFFFFFFFF, state
